import Foundation
@testable import SnippetsCore

// merge-differential <input.json> [<output.json>]
//
// Runs the unmodified Swift merge over inputs generated by the Kotlin tests
// (`MergeDifferentialTest`) and prints one JSON document. Every string that could hold
// text is carried as lowercase hex of its UTF-8, and every double as its IEEE-754 bits,
// so neither side's JSON reader can normalise anything.
//
// Input (every member optional):
//   "merge":  [{"base": <hex|null>, "local": <hex|null>, "remote": <hex|null>}]   canonical envelope bytes
//   "copy":   [<hex>]                                                              canonical envelope bytes
//   "tags":   [{"base": [<hex>]|null, "local": [<hex>], "remote": [<hex>], "localWins": <bool>}]
//   "local":  [{"base": [<snippet>], "local": [<snippet>], "remote": [<snippet>]}]
//   "sorted": [[<hex>]]                                                            Set(strings).sorted()
//   "stamp":  [<16 hex digits>]                                                    updatedAt bits
//   "inspect":  [<hex>]                                                            canonical envelope bytes
//   "converge": see Converge.swift (two real engines over InMemoryTransport)
// <snippet> = {"id", "name": <hex>, "keyword": <hex>, "content": <hex>, "tags": [<hex>],
//              "isEnabled", "isPinned", "createdAt": <bits>, "updatedAt": <bits>}
//
// Output: the same member names, one result per input, in order.
//   merge:  {"survivor": <hex|null>, "copies": [<hex>]} | {"error": "Type.case"}
//   copy:   {"copy": <hex>} | {"error": …}
//   tags:   [<hex>]
//   local:  {"snippets": [<snippet>], "copies": [<snippet>], "disabled": [<uuid>], "attention": <bool>}
//   sorted: [<hex>]
//   stamp:  <hex of the formatted "yyyy-MM-dd HH:mm 'UTC'" text>
//   inspect: {"validate": "ok"|"Type.case", "variants": [{"key","copyID"}]|"Type.case",
//             "unresolved", "unknownVersion", "provenance": {"sourceID","fingerprint"}|null, "validIdentity"}

func fail(_ message: String) -> Never {
    FileHandle.standardError.write(Data("merge-differential: \(message)\n".utf8))
    exit(2)
}

extension Data {
    var hex: String { map { String(format: "%02x", $0) }.joined() }

    init?(hex: String) {
        let digits = Array(hex.utf8)
        guard digits.count % 2 == 0 else { return nil }
        var bytes = [UInt8]()
        bytes.reserveCapacity(digits.count / 2)
        func nibble(_ byte: UInt8) -> UInt8? {
            switch byte {
            case UInt8(ascii: "0")...UInt8(ascii: "9"): return byte - UInt8(ascii: "0")
            case UInt8(ascii: "a")...UInt8(ascii: "f"): return byte - UInt8(ascii: "a") + 10
            default: return nil
            }
        }
        var index = 0
        while index < digits.count {
            guard let high = nibble(digits[index]), let low = nibble(digits[index + 1]) else { return nil }
            bytes.append(high << 4 | low)
            index += 2
        }
        self.init(bytes)
    }
}

func text(_ hex: Any?) -> String {
    guard let hex = hex as? String, let data = Data(hex: hex) else { fail("expected hex text") }
    return String(decoding: data, as: UTF8.self)
}

func hexText(_ value: String) -> String { "\"\(Data(value.utf8).hex)\"" }

func double(_ bits: Any?) -> Double {
    guard let bits = bits as? String, let pattern = UInt64(bits, radix: 16) else { fail("expected double bits") }
    return Double(bitPattern: pattern)
}

func bitsText(_ value: Double) -> String { "\"\(String(format: "%016llx", value.bitPattern))\"" }

/// `Type.case`, without any payload.
func errorName(_ error: Error) -> String {
    let typeName = String(reflecting: type(of: error)).replacingOccurrences(of: "SnippetsCore.", with: "")
    var caseName = String(describing: error)
    if let parenthesis = caseName.firstIndex(of: "(") { caseName = String(caseName[..<parenthesis]) }
    return "\(typeName).\(caseName)"
}

func envelope(_ value: Any?, _ role: String) throws -> SyncEnvelope? {
    if value == nil || value is NSNull { return nil }
    guard let hex = value as? String, let data = Data(hex: hex) else { fail("\(role) is not hex") }
    return try SyncEnvelope.parse(data)
}

func snippet(_ value: Any) -> Snippet {
    guard let object = value as? [String: Any], let idText = object["id"] as? String,
          let id = UUID(uuidString: idText), let tags = object["tags"] as? [Any],
          let isEnabled = object["isEnabled"] as? Bool, let isPinned = object["isPinned"] as? Bool
    else { fail("malformed snippet") }
    return Snippet(
        id: id, name: text(object["name"]), keyword: text(object["keyword"]), content: text(object["content"]),
        tags: tags.map { text($0) }, isEnabled: isEnabled, isPinned: isPinned,
        createdAt: Date(timeIntervalSinceReferenceDate: double(object["createdAt"])),
        updatedAt: Date(timeIntervalSinceReferenceDate: double(object["updatedAt"])))
}

func snippetJSON(_ snippet: Snippet) -> String {
    "{\"id\":\"\(snippet.id.uuidString.lowercased())\",\"name\":\(hexText(snippet.name)),"
        + "\"keyword\":\(hexText(snippet.keyword)),\"content\":\(hexText(snippet.content)),"
        + "\"tags\":[\(snippet.tags.map(hexText).joined(separator: ","))],"
        + "\"isEnabled\":\(snippet.isEnabled),\"isPinned\":\(snippet.isPinned),"
        + "\"createdAt\":\(bitsText(snippet.createdAt.timeIntervalSinceReferenceDate)),"
        + "\"updatedAt\":\(bitsText(snippet.updatedAt.timeIntervalSinceReferenceDate))}"
}

func snippets(_ value: Any?) -> [Snippet] {
    guard let array = value as? [Any] else { fail("expected a snippet array") }
    return array.map(snippet)
}

let arguments = Array(CommandLine.arguments.dropFirst())
guard arguments.count == 1 || arguments.count == 2 else { fail("usage: merge-differential <input.json> [<output.json>]") }
guard let inputData = FileManager.default.contents(atPath: arguments[0]),
      let input = try? JSONSerialization.jsonObject(with: inputData) as? [String: Any]
else { fail("cannot read \(arguments[0])") }

var sections: [String] = []

if let triples = input["merge"] as? [[String: Any]] {
    var results: [String] = []
    results.reserveCapacity(triples.count)
    for triple in triples {
        let base: SyncEnvelope?, local: SyncEnvelope?, remote: SyncEnvelope?
        do {
            base = try envelope(triple["base"], "base")
            local = try envelope(triple["local"], "local")
            remote = try envelope(triple["remote"], "remote")
        } catch {
            results.append("{\"error\":\"input:\(errorName(error))\"}")
            continue
        }
        do {
            let outcome = try SyncMerge.mergeEnvelopeOutcome(base: base, local: local, remote: remote)
            let survivor = try outcome.survivor.map { "\"\(try $0.canonicalData().hex)\"" } ?? "null"
            let copies = try outcome.conflictCopies.map { "\"\(try $0.canonicalData().hex)\"" }
            results.append("{\"survivor\":\(survivor),\"copies\":[\(copies.joined(separator: ","))]}")
        } catch {
            results.append("{\"error\":\"\(errorName(error))\"}")
        }
    }
    sections.append("\"merge\":[\n\(results.joined(separator: ",\n"))\n]")
}

if let sources = input["copy"] as? [Any] {
    var results: [String] = []
    for source in sources {
        do {
            guard let parsed = try envelope(source, "copy source") else { fail("copy source is null") }
            let copy = try SyncMerge.makePlainContentConflictCopy(from: parsed)
            results.append("{\"copy\":\"\(try copy.canonicalData().hex)\"}")
        } catch {
            results.append("{\"error\":\"\(errorName(error))\"}")
        }
    }
    sections.append("\"copy\":[\n\(results.joined(separator: ",\n"))\n]")
}

if let cases = input["tags"] as? [[String: Any]] {
    var results: [String] = []
    for entry in cases {
        guard let local = entry["local"] as? [Any], let remote = entry["remote"] as? [Any],
              let localWins = entry["localWins"] as? Bool else { fail("malformed tags case") }
        let base = (entry["base"] as? [Any])?.map { text($0) }
        let merged = SyncMerge.mergeTags(base, local.map { text($0) }, remote.map { text($0) }, localWins: localWins)
        results.append("[\(merged.map(hexText).joined(separator: ","))]")
    }
    sections.append("\"tags\":[\n\(results.joined(separator: ",\n"))\n]")
}

if let cases = input["local"] as? [[String: Any]] {
    var results: [String] = []
    for entry in cases {
        let outcome = SyncMerge.mergeLocal(
            base: snippets(entry["base"]), local: snippets(entry["local"]), remote: snippets(entry["remote"]))
        results.append(
            "{\"snippets\":[\(outcome.snippets.map(snippetJSON).joined(separator: ","))],"
                + "\"copies\":[\(outcome.conflictCopies.map(snippetJSON).joined(separator: ","))],"
                + "\"disabled\":[\(outcome.disabledByKeywordCollision.map { "\"\($0.uuidString.lowercased())\"" }.joined(separator: ","))],"
                + "\"attention\":\(outcome.needsUserAttention)}")
    }
    sections.append("\"local\":[\n\(results.joined(separator: ",\n"))\n]")
}

if let lists = input["sorted"] as? [[Any]] {
    var results: [String] = []
    for list in lists {
        let sorted = Set(list.map { text($0) }).sorted()
        results.append("[\(sorted.map(hexText).joined(separator: ","))]")
    }
    sections.append("\"sorted\":[\n\(results.joined(separator: ",\n"))\n]")
}

if let stamps = input["stamp"] as? [Any] {
    // The formatter of `SyncMerge.conflictName(for:)`, which is private; the "copy"
    // section checks the real function end to end.
    let formatter = DateFormatter()
    formatter.locale = Locale(identifier: "en_US_POSIX")
    formatter.timeZone = TimeZone(secondsFromGMT: 0)
    formatter.dateFormat = "yyyy-MM-dd HH:mm 'UTC'"
    var results: [String] = []
    for stamp in stamps {
        results.append(hexText(formatter.string(from: Date(timeIntervalSinceReferenceDate: double(stamp)))))
    }
    sections.append("\"stamp\":[\n\(results.joined(separator: ",\n"))\n]")
}

if let envelopes = input["inspect"] as? [Any] {
    // The reserved-key readers the journal and the bridge call on their own.
    var results: [String] = []
    for value in envelopes {
        let parsed: SyncEnvelope
        do {
            guard let envelope = try envelope(value, "inspect") else { fail("inspect entry is null") }
            parsed = envelope
        } catch {
            results.append("{\"error\":\"input:\(errorName(error))\"}")
            continue
        }
        var members: [String] = []
        do {
            try SyncMerge.validateContentConflictExtensions(in: parsed)
            members.append("\"validate\":\"ok\"")
        } catch {
            members.append("\"validate\":\"\(errorName(error))\"")
        }
        do {
            let variants = try SyncMerge.secureContentConflictVariants(in: parsed)
            let listed = variants.map {
                "{\"key\":\"\($0.extensionKey)\",\"copyID\":\"\($0.copyID.uuidString.lowercased())\"}"
            }
            members.append("\"variants\":[\(listed.joined(separator: ","))]")
        } catch {
            members.append("\"variants\":\"\(errorName(error))\"")
        }
        members.append("\"unresolved\":\(SyncMerge.hasUnresolvedContentConflict(parsed))")
        members.append("\"unknownVersion\":\(SyncMerge.hasUnknownContentConflictVersion(parsed))")
        if let provenance = SyncMerge.conflictCopyProvenance(in: parsed) {
            members.append(
                "\"provenance\":{\"sourceID\":\"\(provenance.sourceID.uuidString.lowercased())\","
                    + "\"fingerprint\":\"\(provenance.fingerprint)\"}")
        } else {
            members.append("\"provenance\":null")
        }
        members.append("\"validIdentity\":\(SyncMerge.hasValidConflictCopyIdentity(parsed))")
        results.append("{\(members.joined(separator: ","))}")
    }
    sections.append("\"inspect\":[\n\(results.joined(separator: ",\n"))\n]")
}

if let cases = input["converge"] as? [[String: Any]] {
    let results = await runConverge(cases)
    sections.append("\"converge\":[\n\(results)\n]")
}

let output = Data("{\n\(sections.joined(separator: ",\n"))\n}\n".utf8)
if arguments.count == 2 {
    do { try output.write(to: URL(fileURLWithPath: arguments[1]), options: .atomic) }
    catch { fail("cannot write \(arguments[1])") }
} else {
    FileHandle.standardOutput.write(output)
}
